 fn recover_take_into<'r>(&mut self,output:&mut Option<Box<[T;N]>>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{Self::recover_take_into(self,output,effect,reply)}
 fn close_started(&self)->bool{Self::close_started(self)}
